We start by proving the following 2 auxiliary statements:

\begin{lemma}[Max-Walk Crossing Number]
\label{lemma:max-walk-crossing-number}
Let $X$ be a set of sequences $x \in \R^m$, each having the DSS property, and let $a : X \to \R$.
Then
\[
  \Ex{ C(\bm{M}_X^{+a}) } = O(\sqrt m) \,.
\]
\end{lemma}
\begin{proof}[Proof of \cref{lemma:max-walk-crossing-number}]
First observe that $C(\bm{M}_X^{+a}) \leq 2 \, C_\downarrow(\bm{M}_X^{+a}) + 1$ so
it suffices to bound $C_\downarrow(\bm{M}_X^{+a})$. By definition it holds that
$C_\downarrow(\bm{M}_X^{+a}) \leq L_\downarrow(\bm{M}_X^{+a})$, so by 
\cref{prop:max-walk-bound-q} and \cref{prop:sa-q-bound}, we have
\[
  \Ex{ C_\downarrow(\bm{M}_X^{+a}) } \leq \Ex{\bm{Q}^{(m)}} = O(\sqrt m) \,.\qedhere
\]
\end{proof}

\begin{restatable}{theorem}{thminfbound}\label{thm:inf-bound}
If $S \subseteq \zpm^n$ is convex, then $\Inf(S) = O(n^{3/4} \log^{1/4} n)$.
\end{restatable}
\begin{proof}[Proof of \cref{thm:inf-bound}] Recall the definition of the edge-set $E$ of the ternary cube from \cref{eq:edges} and the set $\midlayers(\ell)$ from \cref{eq:inn_mid_out}. Given $\ell > 0$, let 
\[
E_{\ell} = \left\{(u,v) \in E \colon u,v \in \midlayers(\ell)\right\}
\]
denote the set of edges lying in the middle $\ell$ layers of $\zpm^n$.
We consider the following process which samples a random edge in $\zpm^n$. Define $\ell := \sqrt{2n\log n}$ and $m := \sqrt{\frac{n}{\log n}}$. Let $\cD$ denote the distribution over edges defined by the following procedure.
\begin{enumerate}
    \item Sample $\bm{X}^{(0)} \sim \midlayers(\ell)$.
    \item Choose a random subset $\bm{T} \subseteq \{i \colon \bm{X}^{(0)}_i = 0\}$ with $|\bm{T}| = m$ of coordinates where $\bm{X}^{(0)}$ has a $0$.     \item Let $\bm{\eps} = (\bm{\eps}_1,\ldots,\bm{\eps}_m) \in \{\pm 1\}^m$ be independent Rademacher random variables and let $\bm{\sigma} \colon [m] \to \bm{T}$ be a random bijection.
    \item For each $s \in [m]$, let $\bm{X}^{(s)} = \bm{X}^{(s-1)} + \bm{\eps}_s e_{\bm{\sigma}(s)} =
\bm{X}^{(0)} + \sum_{i=1}^s \bm{\eps}_i e_{\bm{\sigma}(i)}$ where $e_j$ is the unit vector with a $1$ in coordinate $j$.
    \item Choose $\bm{s} \sim [m]$ and return the edge $(\bm{X},\bm{Y})
      = (\bm{X}^{(s-1)},\bm{X}^{(s)})$.
\end{enumerate}
Note that the above process can be equivalently defined as obtaining $\bm{X}^{(s)}$ by selecting a
uniform random coordinate $\bm{i}$ where $\bm{X}^{(s-1)}_{\bm{i}} = 0$ and flipping that bit to a
random value in $\{\pm 1\}$, with equal probability. This results in a random walk
$\bm{X}^{(0)},\bm{X}^{(1)}, \ldots, \bm{X}^{(m)}$ of length $m$ where each $(\bm{X}^{(s-1)},\bm{X}^{(s)})$ is a
random out-going edge from $\bm{X}^{(s-1)}$. We use two main claims regarding this random walk to complete the proof of the theorem. The first is that choosing an edge $(\bm{X},\bm{Y})
\sim \cD$ is approximately the same as choosing a uniformly random edge from the middle layers. 

\begin{claim} \label{clm:unif} Fix any $z \in \midlayers(\ell)$ and $s \in [m]$. Then $\pr[\bm{X}^{(s)} = z] = \Theta(3^{-n})$. I.e., each step of the random walk is approximately uniformly distributed over $\midlayers(\ell)$. As a corollary, for any fixed edge $(u,v) \in E_{\ell}$, we have 
\[
\pr_{(\bm X,\bm Y) \sim \cD}[(\bm X,\bm Y) = (u,v)]
    = \Theta\left(\frac{1}{n \cdot 3^n}\right) \text{.}
\]
\end{claim}

The second claim is that the probability of $(\bm X, \bm Y) \sim \cD$ being an influential edge is small.

\begin{claim}
\label{lem:prob_D}
$\pr_{(\bm X,\bm Y) \sim \cD}[S(\bm X) \neq S(\bm Y)] \leq O\left(\frac{1}{\sqrt m}\right)$.
\end{claim}

We defer the proof of both claims to the end of the section.
We now prove \cref{thm:inf-bound} using \cref{clm:unif} and \cref{lem:prob_D} as follows. Let $E$ denote the edges of the ternary hypercube and let $E_{\ell} = \{(u,v) \in E \colon u,v \in \midlayers(\ell)\}$. By definition,
\begin{align*}
    \Inf(S) = \frac{1}{3^n} \cdot \Big(|\{(u,v) \in E \setminus E_{\ell} \colon S(u) \neq S(v)\}| + |\{(u,v) \in E_{\ell} \colon S(u) \neq S(v)\}|\Big) \text{.}
\end{align*}
The first term is bounded using \cref{fact:chernoff} as 
\begin{align*}
    \frac{|\{(u,v) \in E \setminus E_{\ell} \colon S(u) \neq S(v)\}|}{3^n} \leq \frac{|E \setminus E_{\ell}|}{3^n} \leq 2n \cdot \frac{|\overline{\midlayers(\ell)}|}{3^n} \leq 2n \cdot 2\exp(-\ell^2/2n) = O(1) 
\end{align*}
since every vertex has degree at most $2n$. The second term is bounded as
\begin{align}
    \frac{|\{(u,v) \in E_{\ell} \colon S(u) \neq S(v)\}|}{3^n} &= \frac{|E_{\ell}|}{3^n} \cdot
\pr_{(u,v) \sim E_{\ell}} [S(u) \neq S(v)] \leq \frac{2n}{3} \cdot  \pr_{(u,v) \sim E_{\ell}} [S(u) \neq S(v)] \nonumber \\
    &\leq L n \cdot \pr_{(\bm X,\bm Y) \sim \cD} [S(\bm X) \neq S(\bm Y)] \leq L' n \cdot m^{-1/2} = L' \cdot n^{3/4} \log^{1/4} n \,, \nonumber
\end{align}
where $L, L'$ are absolute constants.  The first inequality follows simply from $E_{\ell} \subset E$
and $|E| = 2n \cdot 3^{n-1}$. The second inequality follows from \cref{clm:unif} and the third
inequality follows from \cref{lem:prob_D}. This completes the proof of \cref{thm:inf-bound}.
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof} The idea is to make use of our upper bound on the influence of convex sets from \cref{thm:inf-bound}. We will need the following slightly different definition of the influence given by \cite{O14}. We will refer to this slightly different notion as \emph{Fourier influence} and will denote it by $\Inf^{\mathsf{Fourier}}(f)$ for clarity. We will show that these definitions are equivalent up to a constant factor. Below, for $x \in \zpm^n$, $i \in [n]$, and
$b \in \zpm$, we write $x^{i \gets b}$ for the vector obtained from $x$ by setting $x_i$ to $b$.



\begin{definition} [Def. 8.17 and 8.22, \cite{O14}] \label{def:operators} For $f \in L^2(\zpm^n, \pi_{1/3}^{\otimes n})$ and $i \in [n]$, the \emph{projection of $f$ onto $i$} is 
\[
\text{E}_i f(x) = \Exp_{b \in \{0,\pm 1\}}[f(x^{i \gets b})] \text{.}
\]
The \emph{$i$'th coordinate Laplacian operator} $\text{L}_i$ is defined as $\text{L}_i f := f - \text{E}_i f$. The \emph{Fourier influence of coordinate $i$ on $f$ is } $\Inf_i^{\mathsf{Fourier}}(f) = \langle f, \text{L}_i f \rangle$. The \emph{total Fourier influence of $f$} is $\Inf^{\mathsf{Fourier}}(f) = \sum_{i=1}^n \Inf_i^{\mathsf{Fourier}}(f)$.
\end{definition}



We will need the two following identities.

\begin{proposition} [Prop. 8.16 and Prop. 8.23, \cite{O14}] \label{prop:identities} Every $f \in L^2(\zpm^n, \pi_{1/3}^{\otimes n})$ satisfies the following two identities:
\begin{enumerate}
    \item $\sum_{\alpha \in \zpm^n} \widehat{f}(\alpha)^2 = \Exp[f^2]$
    \item $\Inf^{\mathsf{Fourier}}(f) = \sum_{\alpha \in \zpm^n} \# \alpha \cdot \widehat{f}(\alpha)^2$
\end{enumerate}
\end{proposition}



\begin{lemma} [Fourier Concentration from Influence] \label{lem:degree-bound} Let $\cF \colon \zpm^n \to \{\pm 1\}$ be a class of functions with Fourier influence upper bounded by $\Inf^{\mathsf{Fourier}}(f) \leq B$ for all $f \in \cF$. Then, for any $\eps > 0$, we have
\[
\sum_{\alpha \in \zpm^n \colon \# \alpha > B/\eps} \widehat{f}(\alpha)^2 \leq \eps \text{.}
\]
\end{lemma}
\begin{proof} By item (1) of \cref{prop:identities}, we have $\sum_{\alpha} f(\alpha)^2 = 1$. Thus, $\sum_{\alpha} \# \alpha \cdot \widehat{f}(\alpha)^2$ is the expectation of $\# \alpha$ when $\alpha$ is sampled with probability $\widehat{f}(\alpha)^2$. By item (2) of \cref{prop:identities} we have
\[
\sum_{\alpha \in \zpm^n} \# \alpha \cdot \widehat{f}(\alpha)^2 = \Inf^{\mathsf{Fourier}}(f) \leq B
\]
and now applying Markov's inequality yields the desired inequality. \end{proof}


\begin{fact} [Equivalence of Influence Definitions] \label{fact:inf-def} For every $f \colon \zpm^n \to \{\pm 1\}$, we have 
\[
\frac{3}{8} \cdot \Inf^{\mathsf{Fourier}}(f) \leq \Inf(f) \leq \frac{3}{4} \cdot \Inf^{\mathsf{Fourier}}(f)\text{.}
\]
\end{fact}

\begin{proof} Let $\Delta_i(f)$ denote the number of lines in the ternary hypercube of the form $(x^{i \gets -1}, x^{i \gets 0}, x^{i \gets 1})$ such that $f_{\{x^{i \gets -1}, x^{i \gets 0}, x^{i \gets 1}\}}$ is not constant, and let $\Delta(f) = \sum_i \Delta_i$ be the total number of such lines. Recall the definition of $\Inf(f)$ from \cref{eq:influence} and observe that since every such line contains either $1$ or $2$ influential edges, we have $\Delta(f) \cdot 3^{-n} \leq \Inf(f) \leq 2\Delta(f) \cdot 3^{-n}$. We will show that $\Inf^{\mathsf{Fourier}}(f) = \frac{8}{3} \Delta(f) \cdot 3^{-n}$ and combining these observations completes the proof. We have
\begin{align}
    \Inf_i^{\mathsf{Fourier}}(f) = \langle f, \text{L}_i f\rangle = \Exp_x\left[f(x)(f(x)-\text{E}_i f(x))\right] = \Exp_x\left[1 - f(x)\Exp_{b \in \{0,\pm 1\}}[f(x^{i \gets b})]\right] \text{.}  
\end{align}
Now, for a fixed $x$, consider the line in dimension $i$, containing $x$: $\ell_i(x) := (x^{i \gets -1}, x^{i \gets 0}, x^{i \gets 1})$. Observe that if $f$ is constant on $\ell_i(x)$, then $1 - f(x)\Exp_{b \in \{0,\pm 1\}}[f(x^{i \gets b})] = 0$. If $f$ is non-constant on $\ell_i(x)$, then either it contains two $+1$'s and one $-1$ or vice versa. In both cases we have
\begin{align}
    \Exp_{a \in \{0,\pm 1\}}\left[1 - f(x^{i \gets a})\Exp_{b \in \{0,\pm 1\}}[f(x^{i \gets b})]\right] = 1 - \Exp_{b \in \zpm}[f(x^{i\gets b})]^2 = 8/9 \text{.}
\end{align}
Therefore, 
\begin{align*}
    \Inf_i^{\mathsf{Fourier}}(f) &= \Exp_x\left[1 - f(x)\Exp_{b \in \{0,\pm 1\}}[f(x^{i \gets b})]\right] = \Exp_x\Exp_{a \in \{0,\pm 1\}}\left[1 - f(x^{i \gets a})\Exp_{b \in \{0,\pm 1\}}[f(x^{i \gets b})]\right] \\
        &= \frac{8}{9} \Exp_x \left[\mathbf{1}(f|_{\ell_i(x)} \text{ is not constant})\right] = \frac{8}{3} \Delta_i(f) \cdot 3^{-n} 
\end{align*}
and summing over all $i$ completes the proof. \end{proof}

Combining \cref{thm:inf-bound}, \cref{lem:degree-bound}, and \cref{fact:inf-def} completes the proof of \cref{lem:concentration}. \end{proof}
